import json, math, os, random, subprocess, sys
R="/mnt/c/dbsvace/vo5/A/task015"; D="/tmp/sweep"; os.makedirs(D, exist_ok=True)
H='OPENQASM 2.0;\ninclude "qelib1.inc";\n'
rng=random.Random(2026)
chans=["amplitude_damping","phase_damping","bit_flip","depolarizing"]
def gate_pool(n):
    p=[f"x q[{i}];\n" for i in range(n)]+[f"h q[{i}];\n" for i in range(n)]
    p+=[f"ry(0.37) q[{i}];\n" for i in range(n)]+[f"rx(1.2) q[{i}];\n" for i in range(n)]
    if n>=2:
        p+=["cx q[0],q[1];\n","cz q[0],q[1];\n","crx(0.6) q[0],q[1];\n"]
    return p
def valid(v):
    if isinstance(v,float): return math.isfinite(v) and 0.0<=v<=1.0
    if isinstance(v,list): return all(valid(x) for x in v)
    return True
bad=0; checked=0
for t in range(400):
    def make():
        n=rng.choice([1,2,3]); pool=gate_pool(n)
        body=f"qreg q[{n}];\ncreg c[{n}];\n"+"".join(rng.choice(pool) for _ in range(rng.randint(1,6)))
        return n, H+body
    nl,bl=make(); nr,br=make()
    open(f"{D}/l.qasm","w").write(bl); open(f"{D}/r.qasm","w").write(br)
    argv=["-m","quantum_circuit.cli","state-metrics",f"{D}/l.qasm",f"{D}/r.qasm"]
    noisy=False
    for side,flag in (("l","--left-noise-model"),("r","--right-noise-model")):
        if rng.random()<0.6:
            m={c: round(rng.random(),3) for c in rng.sample(chans,rng.randint(1,4))}
            p=f"{D}/{side}.json"; open(p,"w").write(json.dumps(m)); argv+=[flag,p]; noisy=True
    pr=subprocess.run([sys.executable,*argv],capture_output=True,text=True,env=dict(os.environ,PYTHONPATH=R))
    if pr.returncode!=0: bad+=1; print("unexpected rc",pr.returncode,pr.stderr); continue
    raw=pr.stdout
    if "NaN" in raw or "Infinity" in raw or "-0" in raw: bad+=1; print("bad token:",raw); continue
    d=json.loads(raw); checked+=1
    assert d["schema_version"]==(2 if noisy else 1)
    if d["fidelity"] is not None: assert valid(d["fidelity"])
    if noisy:
        for k in ("left_purity","right_purity"): assert valid(d[k]), (k,d[k])
    for k in ("left_single_qubit_entropy","right_single_qubit_entropy"):
        assert all(valid(x) for x in d[k])
print(f"checked {checked} runs, BAD={bad}")
